use std::process::ExitCode;

use cryfs_cli::CryfsApp;

fn main() -> ExitCode {
    // Handwritten rather than generated by #[daemonizable::main]: the
    // attribute emits `fn main` right next to the impl block, but
    // `impl Daemonizable for CryfsApp` lives in the cryfs-cli lib (so `Cli`
    // can name `Daemonizer<CryfsApp>` in its field type), and a main emitted
    // there wouldn't be this bin's entry point.
    daemonizable::run::<CryfsApp>()

    // TODO Better error messages for common errors instead of just printing the error stack trace
}

